  "sql": "WITH RECURSIVE bom AS (SELECT mb.component_id, mb.qty FROM model_bom mb WHERE mb.model_id = (SELECT model_id FROM company_model WHERE model_code = 'SW5-160BLK47-0047') AND mb.valid_from <= DATE '2026-10-01' AND (mb.valid_to IS NULL OR mb.valid_to >= DATE '2026-10-01') UNION ALL SELECT cb.child_component_id, b.qty * cb.qty FROM bom b JOIN component_bom cb ON cb.parent_component_id = b.component_id WHERE cb.valid_from <= DATE '2026-10-01' AND (cb.valid_to IS NULL OR cb.valid_to >= DATE '2026-10-01')) SELECT SUM(qty) AS total_qty FROM bom WHERE component_id = (SELECT component_id FROM component WHERE component_code = 'MOT-201-BLK-02665')"
}

